"""Embed API shader sources as checked-in C headers; --check detects stale output.

*.in templates retain @C_MACRO@ substitutions for the shared visual contract
and the GLES/macOS GLSL version. A substitution occupying its own line replaces
that whole line; inline substitutions replace only the marked token.
"""
import argparse
import json
from pathlib import Path
import re

BACKENDS = Path(__file__).resolve().parents[1]
TOKEN = re.compile(r'^@([A-Za-z_]\w*)@\n|@([A-Za-z_]\w*)@', re.MULTILINE)


def c_strings(code):
    return [json.dumps(line, ensure_ascii=True) for line in code.splitlines(keepends=True)]


def generate(source, declaration):
    code = source.read_text(encoding='utf-8')
    parts = []
    offset = 0
    if source.suffix == '.in':
        for match in TOKEN.finditer(code):
            parts.extend(c_strings(code[offset:match.start()]))
            parts.append(match[1] or match[2])
            offset = match.end()
    parts.extend(c_strings(code[offset:]))
    if not parts:
        parts.append('""')
    return ('// Generated by backends/tools/embed_shaders.py. Do not edit.\n'
            f'// Source: {source.relative_to(BACKENDS).as_posix()}\n'
            f'{declaration} =\n' + '\n'.join(parts) + ';\n')


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true', help='check without modifying files')
    args = parser.parse_args()
    stale = []
    count = 0
    for manifest in sorted((BACKENDS / 'renderers').glob('*/shaders/manifest.json')):
        folder = manifest.parent
        for entry in json.loads(manifest.read_text(encoding='utf-8')):
            source = (folder / entry['source']).resolve()
            target = (folder / 'generated' / entry['header']).resolve()
            if not source.is_relative_to(folder) or not target.is_relative_to(folder / 'generated'):
                raise ValueError(f'Invalid shader path in {manifest}')
            expected = generate(source, entry['declaration'])
            actual = target.read_text(encoding='utf-8') if target.exists() else None
            if actual != expected:
                stale.append(str(target.relative_to(BACKENDS)))
                if not args.check:
                    target.parent.mkdir(parents=True, exist_ok=True)
                    target.write_text(expected, encoding='utf-8', newline='\n')
            count += 1
    if args.check and stale:
        print('Stale shader headers:\n' + '\n'.join(stale))
        return 1
    print(f'{count} shader headers checked; {len(stale)} regenerated' if not args.check
          else f'All {count} shader headers are current')
    from compile_vulkan_shaders import check
    spirv_stale = check()
    if spirv_stale:
        print('Vulkan bytecode needs backends/tools/compile_vulkan_shaders.py:\n' + '\n'.join(spirv_stale))
        return 1
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
